-- Staging-only V2 contract fixtures; every publication/opening/evidence write rolls back.
begin;
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception '%',message;end if;end$$;
do $$
declare definition jsonb:='{"intelligence_version":2,"role_context":"Service Crew in a Malaysian F&B outlet: welcome guests, take and serve orders, communicate with the kitchen, respond to customer needs and support colleagues during busy service.","evidence_areas":[{"name":"Customer Handling","priority":"Core","goal":"Understand how the candidate listens, explains and responds to customer needs and complaints.","evidence_guidance":"Concrete customer-facing examples, including transferable retail, volunteering or community service; what they did and why.","follow_up_signals":"A generic claim without actions; unclear escalation or communication; a material ambiguity in the example.","stop_condition":"A usable example or scenario establishes the candidate''s own actions and customer communication. Reuse relevant evidence from other answers."},{"name":"Availability / Start Date","priority":"Core","goal":"Understand the earliest realistic start date and material availability constraints.","evidence_guidance":"A concrete date or bounded time window, notice obligations and known constraints relevant to this opening.","follow_up_signals":"Soon, maybe or an unbounded date; a conflict between stated start timing and an obligation. Clarify once where material.","stop_condition":"Start timing and material limits are explicit, including an honest unknown. An unknown date remains Partial; never demand a positive answer."},{"name":"Shift Flexibility","priority":"Core","goal":"Understand actual shift, weekend and closing availability against this opening''s requirements.","evidence_guidance":"Candidate''s concrete availability and limits. Explain confirmed required closing time and weekends naturally.","follow_up_signals":"Vague evening difficulty, unclear weekday versus weekend scope, or contradictory availability. Verify a material conflict once.","stop_condition":"Relevant shift and weekend limits are clear, even if they do not meet the opening. Covered measures understanding, not suitability. Do not re-ask a settled limit."},{"name":"Relevant Work Experience","priority":"Important","goal":"Understand concrete F&B or transferable responsibilities and relevant examples.","evidence_guidance":"Taking orders, retail service, checking delayed orders, volunteering, community food events and other transferable customer/team work.","follow_up_signals":"A broad job label without responsibilities; uncertainty about the candidate''s own contribution.","stop_condition":"Concrete responsibilities and a useful example are established. Lack of formal F&B employment is not itself missing evidence."},{"name":"Teamwork","priority":"Important","goal":"Understand how the candidate coordinates, helps colleagues and handles practical team difficulties.","evidence_guidance":"Their own actions during a rush, coordination with colleagues or kitchen, helping someone or resolving a disagreement; transferable examples count.","follow_up_signals":"We statements without own contribution, or unclear communication in a material situation.","stop_condition":"A useful example establishes their contribution. A rich customer/work answer may already satisfy this area; do not ask a separate teamwork question."}],"follow_up_guidance":"Choose the next useful move: deepen a relevant thread, clarify material ambiguity, verify an actual contradiction once, use a scenario if real evidence is insufficient, or transition when sufficient. Reuse evidence across areas; never ask dedicated questions for covered areas. Prioritize material opening requirements and unresolved Core evidence within remaining time. Accept transferable experience. Keep one concise question at a time, acknowledge naturally and avoid repetitive praise. Near the end invite candidate questions, answer only confirmed job facts and identify unknowns for the hiring team. After evidence and candidate Q&A, request server completion and close naturally. These are reasoning guidance, never scores or mandatory answer checklists.","scenarios":[{"brief":"A customer complains that their food is taking too long. How would you respond and work with your team?","required":false,"purpose":"Understand practical customer communication and team coordination when an order is delayed.","evidence_areas":["Customer Handling","Teamwork"],"when_to_use":"Use when sufficient equivalent real-world evidence is missing. Skip when the candidate already described handling a comparable delayed-order complaint.","follow_up_guidance":"Ask a useful follow-up about their own communication, checking with the kitchen or escalation only where unclear.","stop_condition":"Their proposed actions and communication are clear enough to understand. Equivalent real-world evidence can satisfy this optional scenario."}],"completion_criteria":{"Core":"covered","Important":"partial","Optional":"unresolved","scenarios":"answered"},"target_minutes":10,"max_minutes":15}'; v1 uuid; v2 uuid; version integer; identity uuid; op uuid; app uuid; token text; aid uuid; client uuid:=gen_random_uuid(); cfg uuid; payload jsonb; r jsonb; tid bigint; ai bigint; question bigint; entity uuid; position uuid;
begin
 select e.auth_user_id into identity from employees e join roles r on r.id=e.role_id where r.name='owner' and e.is_active and e.enable_system_login and e.access_state='active' limit 1;
 perform set_config('request.jwt.claim.sub',identity::text,true);
 select p.id,p.version into v1,version from recruitment_interview_profiles p where profile_key='service_crew' order by p.version desc limit 1;
 perform recruitment_validate_profile(definition);
 v2:=recruitment_publish_profile(definition,version);
 begin perform recruitment_publish_profile(definition,version);raise exception 'Stale publish accepted';exception when serialization_failure then null;end;
 select id into entity from legal_entities where is_active limit 1; select id into position from job_positions where status='active' limit 1;
 payload:=jsonb_build_object('title','QA Intelligence V2 rollback','position_id',position,'workplace','Management','legal_entity_id',entity,'status','open','description','Serve customers and coordinate orders','config',jsonb_build_object('interview_profile_id',v2,'job_facts',jsonb_build_object('offered_salary','RM 2,000 per month (synthetic QA fixture)'),'opening_requirements',jsonb_build_object('weekend_required',true,'closing_shift','Required until 10:30 PM','preferred_start','Within two weeks')));
 op:=recruitment_save_opening(payload);select id into cfg from recruitment_interview_configs where opening_id=op and recruitment_interview_configs.version=1;
 perform pg_temp.assert((select job_facts->>'offered_salary'='RM 2,000 per month (synthetic QA fixture)' and jsonb_typeof(scenario_briefs->0)='string' from recruitment_interview_configs where id=cfg),'Pinned facts/scenario projection lost');
 begin perform recruitment_save_opening(payload||jsonb_build_object('config',jsonb_build_object('interview_profile_id',v2,'job_facts',jsonb_build_object('position','invented'))));raise exception 'Duplicated master fact accepted';exception when invalid_parameter_value then null;end;
 app:=recruitment_register_application(op,jsonb_build_object('full_name','QA V2 rollback','contact','QA-'||op),null);token:=recruitment_issue_invitation(app,clock_timestamp()+interval '1 day');select id into aid from recruitment_public_attempt(token);
 update recruitment_interview_attempts set status='interviewing',lease_owner=client,lease_expires_at=clock_timestamp()+interval '45 seconds',interview_started_at=clock_timestamp(),max_ends_at=clock_timestamp()+interval '15 minutes' where id=aid;
 insert into recruitment_topic_coverage(attempt_id,topic_index,topic) select aid,ordinality-1,value#>>'{}' from jsonb_array_elements((select required_topics from recruitment_interview_configs where id=cfg)) with ordinality;
 insert into recruitment_scenario_progress(attempt_id,scenario_index,brief) select aid,ordinality-1,value#>>'{}' from jsonb_array_elements((select scenario_briefs from recruitment_interview_configs where id=cfg)) with ordinality;
 insert into recruitment_transcript_turns(attempt_id,provider_generation,provider_item_id,speaker,transcript,turn_number,elapsed_end_ms) values(aid,1,'rich','candidate','At a community food event I took orders, listened to a delayed-food complaint, apologised, checked the kitchen and gave an honest update. I helped a colleague during the rush. I can start 15 October, work weekends, but cannot work after 9pm.',1,1000) returning id into tid;
 r:=recruitment_apply_coverage(token,client,'{"topics":[{"index":0,"state":"covered","turn_number":1,"reason":"Listened, checked the kitchen and communicated an update"},{"index":1,"state":"covered","turn_number":1,"reason":"15 October start"},{"index":2,"state":"covered","turn_number":1,"reason":"Weekends available; cannot work after 9pm"},{"index":3,"state":"covered","turn_number":1,"reason":"Transferable community food service responsibilities"},{"index":4,"state":"covered","turn_number":1,"reason":"Helped colleague during rush"}],"scenarios":[],"equivalent_scenarios":[{"index":0,"turn_number":1}]}');
 perform pg_temp.assert((r->>'coverage_complete')::boolean,'Equivalent real evidence did not satisfy optional V2 scenario');
 perform pg_temp.assert((select count(*)=5 from recruitment_topic_coverage where attempt_id=aid and evidence_turn_id=tid and state='covered'),'Rich answer did not support all areas');
 r:=recruitment_assessment_context(token,client);
 perform pg_temp.assert(jsonb_array_length(r->'current_findings')=5 and r->'job_facts'->>'offered_salary' like 'RM 2,000%','Narrow context/facts missing');
 -- Opening edits never rewrite the invited facts or profile.
 perform recruitment_save_opening(payload||jsonb_build_object('id',op,'config',jsonb_build_object('interview_profile_id',v1,'job_facts','{}'::jsonb)));
 perform pg_temp.assert((select config_version_id=cfg from recruitment_interview_attempts where id=aid),'Invited config changed');
 insert into recruitment_transcript_turns(attempt_id,provider_generation,provider_item_id,speaker,transcript,turn_number,elapsed_end_ms) values(aid,1,'question','candidate','Is transport provided after closing?',2,2000) returning id into question;
 insert into recruitment_transcript_turns(attempt_id,provider_generation,provider_item_id,speaker,transcript,turn_number,elapsed_end_ms) values(aid,1,'unknown','ai','That is not confirmed. The hiring team can clarify.',3,3000) returning id into ai;
 perform recruitment_public_finish(token,client,'coverage');
 update recruitment_interview_attempts set status='partial',recording_state='partial' where id=aid;
 perform pg_temp.assert((select count(*)=3 from recruitment_learning_observations where attempt_id=aid and kind in ('candidate_question','unconfirmed_question','knowledge_gap')),'Question/gap observations missing');
 perform pg_temp.assert((select count(*)=1 from recruitment_learning_observations where attempt_id=aid and kind='scenario_usage' and observation like '%equivalent real-world%'),'Scenario observation missing');
 begin perform recruitment_capture_learning(aid,jsonb_build_array(jsonb_build_object('kind','knowledge_gap','observation','Invalid citation','turn_ids',jsonb_build_array(-1))));raise exception 'Foreign citation accepted';exception when raise_exception then if sqlerrm='Foreign citation accepted' then raise;end if;end;
 begin update recruitment_learning_observations set observation='changed' where attempt_id=aid;raise exception 'Observation mutable';exception when object_not_in_prerequisite_state then null;end;
 perform pg_temp.assert((select job_facts->>'offered_salary' like 'RM 2,000%' from recruitment_interview_configs where id=cfg),'Learning modified facts');
 perform pg_temp.assert(not has_function_privilege('anon','recruitment_capture_learning(uuid,jsonb)','EXECUTE') and not has_table_privilege('authenticated','recruitment_learning_observations','SELECT'),'Learning exposed');
 perform pg_temp.assert(not has_function_privilege('anon','recruitment_assessment_context_v1(text,uuid,boolean)','EXECUTE'),'Internal old context exposed');
 perform set_config('request.jwt.claim.sub','',true);
 begin perform recruitment_publish_profile(definition,version+1);raise exception 'Anonymous publish accepted';exception when insufficient_privilege then null;end;
end $$;
rollback;
